SELECT
BT.IMGFILE_DIR AS IMGFILE_DIR, BT.IMGFILE_NAME AS IMGFILE_NAME, BT.SPECIFICATION, BT.MAKER_NAME, BT.MAKER_PART_NO, (SELECT MAX(TEXT2) FROM ICOMCOD1 A, ICOMCQDT B WHERE TYPE = 'M001' AND B.ORIGIN_CODE = A.CODE AND B.BUYER = BT.BUYER AND B.BUYER_ITEM_NO = BT.BUYER_ITEM_NO AND B.STATUS <> 'D') ORIGIN, BT.DESCRIPTION_LOC, BT.BUYER, BT.UNIT_MEASURE, BT.DELIVERY_LT, BT.CATEGORY_TEXT, BT.CATEGORY_NO, BT.STDCATEG_ID, (SELECT COUNT(1) FROM ITEMMAST WHERE STDCATLG_ID = BT.STDCATLG_ID) COUNT ,BT.ITEM_DETAIL_DESC ,BT.MSDS_NO ,BT.DETAIL_IMGFILE_NAME ,BT.DETAIL_IMGFILE_DIR ,(SELECT MAX(A.KEP_USER_ID) FROM MIS_BUYER_MNG A, ICOMLUSR B WHERE A.BUYER = #{com_code} AND A.STATUS ='C' AND A.POSITION_GROUP ='PM' AND B.COM_CODE = 'KRKORE0001' AND A.KEP_USER_ID = B.USER_ID AND B.STATUS IN ('C','R') AND A.YEAR = TO_CHAR(SYSDATE,'YYYY')) AS USER_ID ,(SELECT MAX(B.DEPARTMENT) FROM MIS_BUYER_MNG A, ICOMLUSR B WHERE A.BUYER = #{com_code} AND A.STATUS ='C' AND A.POSITION_GROUP ='PM' AND B.COM_CODE = 'KRKORE0001' AND A.KEP_USER_ID = B.USER_ID AND B.STATUS IN ('C','R') AND A.YEAR = TO_CHAR(SYSDATE,'YYYY')) AS DEPARTMENT ,BT.DESCRIPTION_ENG ,BT.SPECIFICATION_ENG ,BT.IMAGE_KEY ,BT.SAFETY_FLAG ,(SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M160' AND COD.CODE = BT.SAFETY_FLAG) SAFETY_FLAG_TEXT ,BT.BUY_GREEN_ITEM_NM ,BT.DETAIL_ITEM_INFO ,(SELECT DECODE(COUNT(IMP.COL01_DATA), 0, '', MAX(IMP.COL01_DATA)) FROM BNTSLGDEF DEF, BNTSLGIMP IMP WHERE DEF.SLG_ID = IMP.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN DEF.OPEN_DATE AND DEF.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN IMP.OPEN_DATE AND IMP.CLOSE_DATE AND DEF.SLG_ID = 'P07-0000033' AND IMP.COM_CODE = #{com_code}) AS P070000033_CHECK ,(SELECT DECODE(COUNT(COD.CODE),0,'N','Y') FROM ICOMCOD1 COD WHERE 1=1 AND COD.CODE = BT.CMS_CATEG_ID AND COD.TYPE = 'CM11' AND COD.TEXT1 = 'Y' AND COD.FLAG = 'Y') AS SG118_CHECK , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M203' AND CODE = BT.TEMP_COND AND FLAG = 'Y') AS TEMP_COND , BT.TEMP_RANGE , DECODE(BT.MATERIAL_TYPE, 'H', 'Y', 'N') AS HARMFUL_YN FROM ICOMBYIT BT, CMSCATLG CMS, ICOMCQDT CQ WHERE BT.BUYER = #{buyer} AND BT.BUYER_ITEM_NO = #{buyer_tem_no} AND BT.STATUS <> 'D' AND BT.CMS_CATLG_ID = CMS.CMS_CATLG_ID(+) AND CMS.STD_FLAG(+)='Y' AND BT.BUYER = CQ.BUYER AND BT.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO AND CQ.STATUS <> 'D' AND CQ.BELOW_COMORG_CODE = #{com_code}
AND BT.PRODUCT_CLOSE_FLAG IN ('N','Y')
AND BT.PRODUCT_CLOSE_FLAG = 'N'

/*selectbuyerMdCmGoodsLisDetail_CatalogDisplayMain_v2*/
SELECT
BT.IMGFILE_DIR AS IMGFILE_DIR, BT.IMGFILE_NAME AS IMGFILE_NAME, BT.SPECIFICATION, BT.MAKER_NAME, BT.MAKER_PART_NO, (SELECT MAX(TEXT2) FROM ICOMCOD1 A, ICOMCQDT B WHERE TYPE = 'M001' AND B.ORIGIN_CODE = A.CODE AND B.BUYER = BT.BUYER AND B.BUYER_ITEM_NO = BT.BUYER_ITEM_NO AND B.STATUS <> 'D') ORIGIN, BT.DESCRIPTION_LOC, BT.BUYER, BT.UNIT_MEASURE, BT.DELIVERY_LT, BT.CATEGORY_TEXT, BT.CATEGORY_NO, BT.STDCATEG_ID, (SELECT COUNT(1) FROM ITEMMAST WHERE STDCATLG_ID = BT.STDCATLG_ID) COUNT ,BT.ITEM_DETAIL_DESC ,BT.MSDS_NO ,BT.DETAIL_IMGFILE_NAME ,BT.DETAIL_IMGFILE_DIR ,(SELECT MAX(A.KEP_USER_ID) FROM MIS_BUYER_MNG A, ICOMLUSR B WHERE A.BUYER = #{com_code} AND A.STATUS ='C' AND A.POSITION_GROUP ='PM' AND B.COM_CODE = 'KRKORE0001' AND A.KEP_USER_ID = B.USER_ID AND B.STATUS IN ('C','R') AND A.YEAR = TO_CHAR(SYSDATE,'YYYY')) AS USER_ID ,(SELECT MAX(B.DEPARTMENT) FROM MIS_BUYER_MNG A, ICOMLUSR B WHERE A.BUYER = #{com_code} AND A.STATUS ='C' AND A.POSITION_GROUP ='PM' AND B.COM_CODE = 'KRKORE0001' AND A.KEP_USER_ID = B.USER_ID AND B.STATUS IN ('C','R') AND A.YEAR = TO_CHAR(SYSDATE,'YYYY')) AS DEPARTMENT ,BT.DESCRIPTION_ENG ,BT.SPECIFICATION_ENG ,BT.IMAGE_KEY ,(SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = BT.IMAGE_KEY) AS IMAGE_CNT ,BT.SAFETY_FLAG ,(SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M160' AND COD.CODE = BT.SAFETY_FLAG) SAFETY_FLAG_TEXT ,BT.BUY_GREEN_ITEM_NM ,BT.DETAIL_ITEM_INFO ,(SELECT DECODE(COUNT(IMP.COL01_DATA), 0, '', MAX(IMP.COL01_DATA)) FROM BNTSLGDEF DEF, BNTSLGIMP IMP WHERE DEF.SLG_ID = IMP.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN DEF.OPEN_DATE AND DEF.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN IMP.OPEN_DATE AND IMP.CLOSE_DATE AND DEF.SLG_ID = 'P07-0000033' AND IMP.COM_CODE = #{com_code}) AS P070000033_CHECK ,(SELECT DECODE(COUNT(COD.CODE),0,'N','Y') FROM ICOMCOD1 COD WHERE 1=1 AND COD.CODE = BT.CMS_CATEG_ID AND COD.TYPE = 'CM11' AND COD.TEXT1 = 'Y' AND COD.FLAG = 'Y') AS SG118_CHECK , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M203' AND CODE = BT.TEMP_COND AND FLAG = 'Y') AS TEMP_COND , BT.TEMP_RANGE , DECODE(BT.MATERIAL_TYPE, 'H', 'Y', 'N') AS HARMFUL_YN , BT.BUYER_ITEM_NO , BT.OVER_SHORT_FLAG , (SELECT DECODE(COUNT(*),0,'N','Y') FROM ICOMCART WHERE BUYER = #{com_code} AND BUYER_ITEM_NO = #{buyer_tem_no} AND BYIT_COMORG_CODE = #{buyer} AND USE_FLAG = 'R' AND USER_ID = #{user_id}) AS MY_ITEM_YN , BT.MAKER_PART_NO FROM ICOMBYIT BT, CMSCATLG CMS, ICOMCQDT CQ WHERE BT.BUYER = #{buyer} AND BT.BUYER_ITEM_NO = #{buyer_tem_no} AND BT.STATUS <> 'D' AND BT.CMS_CATLG_ID = CMS.CMS_CATLG_ID(+) AND CMS.STD_FLAG(+)='Y' AND BT.BUYER = CQ.BUYER AND BT.BUYER_ITEM_NO = CQ.BUYER_ITEM_NO AND CQ.STATUS <> 'D' AND CQ.BELOW_COMORG_CODE = #{com_code}
AND BT.PRODUCT_CLOSE_FLAG IN ('N','Y')
AND BT.PRODUCT_CLOSE_FLAG = 'N'

/*selectbuyerMdCmGoodsLisDetail_PCOItemSeries*/
SELECT DISTINCT '협력사' TEXT1, --[00] '품목코드' TEXT2, --[01] '단가' TEXT3, --[02] '신청수량' TEXT4, --[03] (SELECT ATTB_NM1 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM1 , --[04] (SELECT ATTB_NM2 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM2 , --[05] (SELECT ATTB_NM3 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM3 , --[06] (SELECT ATTB_NM4 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM4 , --[07] (SELECT ATTB_NM5 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM5 , --[08] DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{buyer} ),'N','코리아E플랫폼(주)',(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT)) COM_NAME_LOC, --[09] A.BUYER_ITEM_NO, --[10] TO_CHAR(A.UNIT_PRICE) UNIT_PRICE, --[11] '' TEXT5, --[12] B.ATTB_NM1, --[13] B.ATTB_NM2, --[14] B.ATTB_NM3, --[15] B.ATTB_NM4, --[16] B.ATTB_NM5, --[17] A.DESCRIPTION, --[18] A.SPECIFICATION, --[19] A.CONTRACT_NO, --[20] A.CONTRACT_SEQ, --[21] C.CATEGORY_NO, --[22] C.CATEGORY_TEXT, --[23] A.AGENT, --[24] A.BUYER, --[25] '2' AGENT_NM, --[26] C.PRODUCT_CLOSE_FLAG FROM ICOMCQDT A, ITEMMAST B, ICOMBYIT C WHERE A.BUYER = #{buyer}
AND C.STDCATLG_ID =#{stdcatlg_id}
AND C.STDCATLG_ID = B.STDCATLG_ID(+) AND A.BUYER = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.STATUS <> 'D' AND B.STATUS(+) <> 'D' AND C.STATUS <> 'D' AND C.PRODUCT_CLOSE_FLAG <> 'S' AND A.BELOW_COMORG_CODE =#{com_code}
AND C.BUYER_ITEM_NO = #{buyer_tem_no} ORDER BY AGENT_NM ,1

/*selectbuyerMdCmGoodsLisDetail_ItemSeries*/
SELECT DISTINCT '협력사' TEXT1, --[00] '품목코드' TEXT2, --[01] '단가' TEXT3, --[02] '신청수량' TEXT4, --[03] (SELECT ATTB_NM1 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM1 , --[04] (SELECT ATTB_NM2 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM2 , --[05] (SELECT ATTB_NM3 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM3 , --[06] (SELECT ATTB_NM4 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM4 , --[07] (SELECT ATTB_NM5 FROM ITEMATTR WHERE STDCATEG_ID = #{stdcateg_id} ) AS ATTB_NM5 , --[08] DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{buyer} ),'N','코리아E플랫폼(주)',(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT)) COM_NAME_LOC, --[09] A.BUYER_ITEM_NO, --[10] TO_CHAR(A.UNIT_PRICE) UNIT_PRICE, --[11] '' TEXT5, --[12] NVL(B.ATTB_NM1, ' ') AS ATTB1, --[13] NVL(B.ATTB_NM2, ' ') AS ATTB2, --[14] NVL(B.ATTB_NM3, ' ') AS ATTB3, --[15] NVL(B.ATTB_NM4, ' ') AS ATTB4, --[16] NVL(B.ATTB_NM5, ' ') AS ATTB5, --[17] A.DESCRIPTION, --[18] A.SPECIFICATION, --[19] A.CONTRACT_NO, --[20] A.CONTRACT_SEQ, --[21] C.CATEGORY_NO, --[22] C.CATEGORY_TEXT, --[23] A.AGENT, --[24] A.BUYER, --[25] '2' AGENT_NM, --[26] A.MIN_ORDER_QTY, A.PUR_UNIT_QTY, A.DELIVERY_LT, NVL((SELECT COD.VALUE1 FROM ICOMCOD2 COD WHERE COD.TYPE ='WMST' AND COD.CODE = A.BUYER||A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ AND COD.FLAG ='Y'),'') AS STOCK_CNT FROM ICOMCQDT A, ITEMMAST B, ICOMBYIT C WHERE A.BUYER = #{buyer}
AND C.STDCATLG_ID =#{stdcatlg_id}
AND C.STDCATLG_ID = B.STDCATLG_ID(+) AND A.BUYER = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.STATUS IN('C','R') AND B.STATUS(+) <> 'D' AND C.STATUS IN('C','R')
AND C.PRODUCT_CLOSE_FLAG IN ('N','Y')
AND C.PRODUCT_CLOSE_FLAG = 'N'
AND A.BELOW_COMORG_CODE =#{com_code}
AND C.BUYER_ITEM_NO = #{buyer_tem_no} ORDER BY AGENT_NM ,1

/*selectbuyerMdCmGoodsLisDetail_ItemSeries_v2*/
SELECT DISTINCT '협력사' TEXT1, --[00] '품목코드' TEXT2, --[01] '단가' TEXT3, --[02] '신청수량' TEXT4, --[03] DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{buyer} ),'N','코리아이플랫폼(주)',(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT)) COM_NAME_LOC, --[09] A.BUYER_ITEM_NO, --[10] TO_CHAR(A.UNIT_PRICE) UNIT_PRICE, --[11] '' TEXT5, --[12] A.DESCRIPTION, --[18] A.SPECIFICATION, --[19] A.CONTRACT_NO, --[20] A.CONTRACT_SEQ, --[21] C.CATEGORY_NO, --[22] C.CATEGORY_TEXT, --[23] A.AGENT, --[24] A.BUYER, --[25] '2' AGENT_NM, --[26] A.MIN_ORDER_QTY, NVL(A.PUR_UNIT_QTY,1) AS PUR_UNIT_QTY, A.DELIVERY_LT, NVL((SELECT COD.VALUE1 FROM ICOMCOD2 COD WHERE COD.TYPE ='WMST' AND COD.CODE = A.BUYER||A.BUYER_ITEM_NO||A.CONTRACT_NO||A.CONTRACT_SEQ AND COD.FLAG ='Y'),'') AS STOCK_CNT, COUNT(*) OVER (PARTITION BY C.BUYER_ITEM_NO) AS LINE_CNT FROM ICOMCQDT A, ICOMBYIT C WHERE A.BUYER = #{buyer} AND A.BUYER = C.BUYER AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.STATUS <> 'D' AND C.STATUS <> 'D'
AND C.PRODUCT_CLOSE_FLAG IN ('N','Y')
AND A.BELOW_COMORG_CODE =#{com_code}
AND C.BUYER_ITEM_NO IN
#{item}
ORDER BY BUYER_ITEM_NO,UNIT_PRICE,COM_NAME_LOC

