SELECT COUNT(1) CNT FROM ICOMCART WHERE BUYER = #{BUYER} AND USER_ID = #{USER_ID} AND USE_FLAG = #{USE_FLAG} AND BUYER_ITEM_NO = #{BUYER_ITEM_NO} AND AGENT = #{AGENT} AND CONTRACT_NO = #{CONTRACT_NO} AND CONTRACT_SEQ = #{CONTRACT_SEQ} AND BYIT_COMORG_CODE = #{BYIT_COMORG_CODE}
AND MY_GROUP = #{MY_GROUP}
AND (MY_GROUP IS NULL OR MY_GROUP = 'MCDEFAULT')
AND NVL(PRE_GR_FLAG,'N') = 'N'



/*getItemNoCheck2_v2*/

SELECT COUNT(1) CNT FROM ICOMCART           
 WHERE BUYER          		= #{BUYER}                
   AND USER_ID        			= #{USER_ID}               
   AND USE_FLAG       		= #{USE_FLAG}           
   AND CONTRACT_NO    	= #{CONTRACT_NO}                
   AND CONTRACT_SEQ   	= #{CONTRACT_SEQ}


		AND MY_GROUP = #{MY_GROUP}


		AND (MY_GROUP IS NULL OR MY_GROUP = 'MCDEFAULT')


   AND NVL(PRE_GR_FLAG,'N') = 'N'


/*getStQueryCartValue*/
SELECT BUYER_ITEM_NO||CONTRACT_NO||CONTRACT_SEQ||TO_CHAR(DECODE(MAX(SEQ), NULL, '0', MAX(SEQ)))||'@@' AS ST_QUERY_CART 
  FROM ICOMCART 
 WHERE BUYER = #{BUYER} 
   AND USER_ID = #{USER_ID} 
   AND BUYER_ITEM_NO = #{BUYER_ITEM_NO} 
   AND CONTRACT_NO = #{CONTRACT_NO} 
   AND CONTRACT_SEQ = #{CONTRACT_SEQ} 
   AND USE_FLAG = #{USE_FLAG}
 GROUP BY BUYER_ITEM_NO, CONTRACT_NO, CONTRACT_SEQ

