INSERT INTO COWAY_CART (
BUYER, USER_ID, BUYER_ITEM_NO, SEQ, REG_DATE, USE_FLAG, AGENT, CONTRACT_NO, CONTRACT_SEQ, BYIT_COMORG_CODE, MG_NOTE ,IMAGE_KEY
) VALUES (
#{BUYER}, -- 1 BUYER, #{USER_ID}, -- 2 USER_ID #{BUYER_ITEM_NO}, -- 3 BUYER_ITEM_NO (SELECT DECODE(MAX(SEQ),NULL,'0', MAX(SEQ))+1 FROM COWAY_CART WHERE BUYER = #{BUYER} -- 4 BUYER AND USER_ID = #{USER_ID} -- 5 USER_ID AND BUYER_ITEM_NO = #{BUYER_ITEM_NO} -- 6 BUYER_ITEM_NO AND CONTRACT_NO = #{CONTRACT_NO} -- 7 CONTRACT_NO AND CONTRACT_SEQ = #{CONTRACT_SEQ} -- 8 CONTRACT_SEQ ), -- 9 USE_FLAG TO_CHAR(SYSDATE,'YYYYMMDD'), -- REG_DATE #{USE_FLAG}, -- 11 USE_FLAG #{AGENT}, -- 12 AGENT #{CONTRACT_NO}, -- 13 CONTRACT_NO #{CONTRACT_SEQ}, -- 14 CONTRACT_SEQ #{BYIT_COMORG_CODE}, -- 15 BYIT_COMORG_CODE #{REF_PR_NO}, #{IMAGE_KEY} )
